  for(e = eS - OUT; e >= eS - OUT - 330 && e > 30; e--){ for(len = 18; len <= 26; len++){ s = e - len + 1; sq = GU.substr(s - 1, len);
    var tm = pdTm(sq), gc = pdGC(sq); if(tm < 57 || tm > 63 || gc < 40 || gc > 60) continue; if(hit(s, e) || !pdOk(sq, GU, GR)) continue;
    cand.F.push({s:s, e:e, seq:sq, tm:tm, gc:gc, sc:Math.abs(tm - 60) + Math.abs(gc - 50)/10 + Math.abs(len - 22)*0.2}); } }
