  function heroLoc(){ var E = plan.ex; if(E && v.rb < E[1]) return pt('hero_intron', {n:E[0] - 1}); if(E && v.ra > E[2]) return pt('hero_intron', {n:E[0]}); return pt('hero_exon', {n:exn}); }
  function exonOf(r){ for(var i = 0; i < GEXON.length; i++) if(r >= GEXON[i][1] && r <= GEXON[i][2]) return true; return false; }
